--------------OrionMode_t Lookup table -------------------------
-- The mode of operation of the gimbal.
function get_OrionMode_t_string(OrionMode_t)
    if OrionMode_t == 0 then return "ORION_MODE_DISABLED" -- disable motor output
    elseif OrionMode_t == 1 then return "ORION_MODE_FAULT" -- Gimbal has experienced a fault and motors have been disabled
    elseif OrionMode_t == 16 then return "ORION_MODE_RATE" -- Commands give the line of sight angular rate of the camera
    elseif OrionMode_t == 17 then return "ORION_MODE_GEO_RATE" -- Inertial rate mode, with bulk motion compensation when valid slant range is available
    elseif OrionMode_t == 32 then return "ORION_MODE_FFC_AUTO" -- Commands the gimbal to perform a flat field correction, pan and tilt will drive the IR camera to look at the black body
    elseif OrionMode_t == 32 then return "ORION_MODE_FFC" -- Legacy FFC mode, alias of ORION_MODE_FFC_AUTO
    elseif OrionMode_t == 33 then return "ORION_MODE_FFC_MANUAL" -- Commands the gimbal to perform a flat field correction, pan and tilt will drive the IR camera to the commanded positions. NOTE: The pan/tilt targets specify the payload position, not the boresight position, so the reported angles may not match the command target
    elseif OrionMode_t == 48 then return "ORION_MODE_SCENE" -- Commands give the angular rate of the image produced by the camera
    elseif OrionMode_t == 49 then return "ORION_MODE_TRACK" -- Commands give the angular position of the track box in the camera image as fraction from center, bound these numbers -0.5 to 0.5
    elseif OrionMode_t == 50 then return "ORION_MODE_NUDGE_TRACK" -- (Deprecated) Use ORION_PKT_TRACK_CMD
    elseif OrionMode_t == 51 then return "ORION_MODE_SECONDARY_TRACK" -- (Deprecated) Use ORION_PKT_TRACK_CMD
    elseif OrionMode_t == 64 then return "ORION_MODE_CALIBRATION" -- Drives the pan and tilt axes to calibrate the stabilization gyros
    elseif OrionMode_t == 65 then return "ORION_MODE_NULL_GYROS" -- Hold gimbal still while stabilization gyro and IMU gyro biases are estimated. User ensures that crown will not move while in this mode.
    elseif OrionMode_t == 80 then return "ORION_MODE_POSITION" -- Commands give the position of the pan and tilt axes with respect to the gimbal mount
    elseif OrionMode_t == 81 then return "ORION_MODE_POSITION_NO_LIMITS" -- Commands give the position of the pan and tilt axes with respect to the gimbal mount. NOTE: This mode ignores the pan/tilt limits and can result in serious damage to the gimbal if used incorrectly
    elseif OrionMode_t == 96 then return "ORION_MODE_GEOPOINT" -- Gimbal is pointing toward a fixed spatial location
    elseif OrionMode_t == 112 then return "ORION_MODE_PATH" -- Gimbal is pointing toward a fixed path in space, and may be doing step-stare
    elseif OrionMode_t == 113 then return "ORION_MODE_DOWN" -- Gimbal is pointing straight down, and may be doing step-stare
    elseif OrionMode_t == 255 then return "ORION_MODE_UNKNOWN" -- Unknown gimbal mode. This is unused in normal operation and is strictly to maintain compatibility with v1.2
    end
    return "Unknown Value ( " .. OrionMode_t .. " )"
end

