-- Compresssed date format.
function print_Date_t(subtree, memberName, buffer, id, size, index, structSize, arraySize)
    if size == 0 then
        return index
    end
    local indexOffset = index
    for i=0, arraySize-1 do
        local name
        if arraySize > 1 then
            name = memberName .. "[" .. i + 1 .. "]"
        else
            name = memberName
        end
        if(structSize > size - indexOffset) then
            structSize = size - indexOffset
        end
        local Date_tree = makeStructureSubtreeOrionPublic(subtree, buffer(indexOffset, structSize), name, structSize)
        local year, month, day
    --  3 Data Elements found:
        if size >= indexOffset + 2 then
            year = buffer(indexOffset, 1):bitfield(0, 7) + 2000  --  Primitive  year  Type: [unsigned] size in bits:7
            Date_tree:add(buffer(indexOffset, 1), "year: " .. buffer(indexOffset, 1):bitfield(0, 7) + 2000)
            month = buffer(indexOffset, 2):bitfield(7, 4)  --  Primitive  month  Type: [unsigned] size in bits:4
            Date_tree:add(buffer(indexOffset, 2), "month: " .. buffer(indexOffset, 2):bitfield(7, 4))
            day = buffer(indexOffset, 2):bitfield(11, 5)  --  Primitive  day  Type: [unsigned] size in bits:5
            Date_tree:add(buffer(indexOffset, 2), "day: " .. buffer(indexOffset, 2):bitfield(11, 5))
                indexOffset = indexOffset + 2
        end
    end

    return indexOffset
end

