    if size >= (indexOffset + 1)  then
        state = buffer(indexOffset, 1):uint()  --  Enumeration  state  Type: [ScanPlanState_t] size in bits: 8
        OrionScanPlan_tree:add(buffer(indexOffset, 1), "state: " .. get_ScanPlanState_t_string(buffer(indexOffset, 1):uint() )  .. " [" .. buffer(indexOffset, 1):uint() .. "]")
        indexOffset = indexOffset + 1
    end
    if size >= (indexOffset + 1)  then
        horizontalScan = buffer(indexOffset, 1):uint()  --  Primitive  horizontalScan  Type: [uint8_t] size in bits:8
        OrionScanPlan_tree:add(buffer(indexOffset, 1), "horizontalScan: " .. buffer(indexOffset, 1):uint())
        indexOffset = indexOffset + 1
    end
    if size >= (indexOffset + 1)  then
        usePercentHorizon = buffer(indexOffset, 1):uint()  --  Primitive  usePercentHorizon  Type: [uint8_t] size in bits:8
        OrionScanPlan_tree:add(buffer(indexOffset, 1), "usePercentHorizon: " .. buffer(indexOffset, 1):uint())
        indexOffset = indexOffset + 1
    end
    if size >= (indexOffset + 1)  then
        useTargetHfov = buffer(indexOffset, 1):uint()  --  Primitive  useTargetHfov  Type: [uint8_t] size in bits:8
        OrionScanPlan_tree:add(buffer(indexOffset, 1), "useTargetHfov: " .. buffer(indexOffset, 1):uint())
        indexOffset = indexOffset + 1
    end
    if size >= (indexOffset + 1)  then
        referenceFrame = buffer(indexOffset, 1):uint()  --  Enumeration  referenceFrame  Type: [ScanPlanReferenceFrame_t] size in bits: 8
        OrionScanPlan_tree:add(buffer(indexOffset, 1), "referenceFrame: " .. get_ScanPlanReferenceFrame_t_string(buffer(indexOffset, 1):uint() )  .. " [" .. buffer(indexOffset, 1):uint() .. "]")
        indexOffset = indexOffset + 1
    end
    if size >= (indexOffset + 1)  then
        enableAutonomousRate = buffer(indexOffset, 1):uint()  --  Primitive  enableAutonomousRate  Type: [uint8_t] size in bits:8
        OrionScanPlan_tree:add(buffer(indexOffset, 1), "enableAutonomousRate: " .. buffer(indexOffset, 1):uint())
        indexOffset = indexOffset + 1
    end
    if size >= (indexOffset + 4)  then
        sweepAngleDeg = buffer(indexOffset, 4):uint() / 100  --  Primitive  sweepAngleDeg  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "sweepAngleDeg: " .. buffer(indexOffset, 4):uint() / 100 .. "°")
        indexOffset = indexOffset + 4
    end
    if size >= (indexOffset + 4)  then
        hfovRateDeg = buffer(indexOffset, 4):uint() / 100  --  Primitive  hfovRateDeg  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "hfovRateDeg: " .. buffer(indexOffset, 4):uint() / 100 .. " deg/s")
        indexOffset = indexOffset + 4
    end
    if size >= (indexOffset + 4)  then
        hfovDeg = buffer(indexOffset, 4):uint() / 100  --  Primitive  hfovDeg  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "hfovDeg: " .. buffer(indexOffset, 4):uint() / 100 .. "°")
        indexOffset = indexOffset + 4
    end
    if size >= (indexOffset + 4)  then
        maxTargetDistanceKm = buffer(indexOffset, 4):uint() / 100  --  Primitive  maxTargetDistanceKm  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "maxTargetDistanceKm: " .. buffer(indexOffset, 4):uint() / 100 .. " Km")
        indexOffset = indexOffset + 4
    end
    if size >= (indexOffset + 4)  then
        minTargetDistanceKm = buffer(indexOffset, 4):uint() / 100  --  Primitive  minTargetDistanceKm  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "minTargetDistanceKm: " .. buffer(indexOffset, 4):uint() / 100 .. " Km")
        indexOffset = indexOffset + 4
    end
    if size >= (indexOffset + 4)  then
        horizonPercent = buffer(indexOffset, 4):int() / 100  --  Primitive  horizonPercent  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "horizonPercent: " .. buffer(indexOffset, 4):int() / 100 .. "%")
        indexOffset = indexOffset + 4
    end
    if size >= (indexOffset + 4)  then
        yawOffsetDeg = buffer(indexOffset, 4):int() / 100  --  Primitive  yawOffsetDeg  Type: [float] size in bits:32
        OrionScanPlan_tree:add(buffer(indexOffset, 4), "yawOffsetDeg: " .. buffer(indexOffset, 4):int() / 100 .. "°")
        indexOffset = indexOffset + 4
    end
    return name
end

