    else
        info = addUnknownOrionPublicPacket(subtree, data, id, size)
    end
    if tostring(pinfo.cols.info) == "" then
        pinfo.cols.info = info
    else
        pinfo.cols.info = tostring(pinfo.cols.info) .. ", " .. info
    end
    return size + getOrionPublicHeaderLength()
end

-- create a function to dissect it
function OrionPublic.dissector(buffer, pinfo, tree)
    if checkIsOrionPublicPacket(buffer) then
        pinfo.cols.protocol = "OrionPublic"
        local i = 0
        local index = 0
        local bytes = buffer:len()

        pinfo.cols.info = ""

        while i < bytes do
            i = i + print_OrionPublicpacket(pinfo, tree, buffer(i, bytes - i), index)
            index = index + 1
        end
    end
end

registerOrionPublicDissectorTable()
